                if iszero(n) {
                    mstore(0x00, 0xd76f470b) // `HeapIsEmpty()`.
                    revert(0x1c, 0x04)
                }
                popped := sload(offset)
                // Sift down.
                let i := 0
                for {} 1 {} {
                    let c := add(add(i, i), 1)
                    if iszero(lt(c, n)) { break }
                    let cv := sload(add(offset, c))
                    let r := add(c, 1)
                    if lt(r, n) {
                        let rv := sload(add(offset, r))
                        if lt(rv, cv) {
                            c := r
                            cv := rv
                        }
                    }
                    if iszero(lt(cv, value)) { break }
                    sstore(add(offset, i), cv)
                    i := c
                }
                sstore(add(offset, i), value)
                status := 3
                break
            }

            // Mode 4: PushPop
            if eq(mode, 4) {
                if iszero(n) {
                    popped := value
                    break
                }
                let root := sload(offset)
                if iszero(lt(value, root)) {
                    popped := root
                    // Sift down with new value.
                    let i := 0
                    for {} 1 {} {
                        let c := add(add(i, i), 1)
                        if iszero(lt(c, n)) { break }
                        let cv := sload(add(offset, c))
                        let r := add(c, 1)
                        if lt(r, n) {
                            let rv := sload(add(offset, r))
                            if lt(rv, cv) {
                                c := r
                                cv := rv
                            }
                        }
                        if iszero(lt(cv, value)) { break }
                        sstore(add(offset, i), cv)
                        i := c
                    }
                    sstore(add(offset, i), value)
                    break
                }
                popped := root
                sstore(offset, value)
                break
            }

            // Mode 0: Enqueue
            if eq(mode, 0) {
                if iszero(lt(n, maxLength)) {
                    let root := sload(offset)
                    if iszero(lt(value, root)) {
                        // Replace root and sift down.
                        let i := 0
                        for {} 1 {} {
                            let c := add(add(i, i), 1)
                            if iszero(lt(c, n)) { break }
                            let cv := sload(add(offset, c))
                            let r := add(c, 1)
                            if lt(r, n) {
                                let rv := sload(add(offset, r))
                                if lt(rv, cv) {
                                    c := r
                                    cv := rv
                                }
                            }
                            if iszero(lt(cv, value)) { break }
                            sstore(add(offset, i), cv)
                            i := c
                        }
                        sstore(add(offset, i), value)
                        popped := root
                        status := 3
                        break
                    }
                    // Value is smaller than root, discard.
                    break
                }
                // Push the value.
                n := add(n, 1)
                sstore(heap.data.slot, n)
                // Sift up.
                let i := sub(n, 1)
                for {} i {} {
                    let p := shr(1, sub(i, 1))
                    let pv := sload(add(offset, p))
                    if iszero(lt(value, pv)) { break }
                    sstore(add(offset, i), pv)
                    i := p
                }
                sstore(add(offset, i), value)
                status := 1
