    ///
    /// @return status The status of the operation:
    ///              - 1: Successfully enqueued.
    ///              - 3: Replaced the root value.
    ///              - Other: Operation-specific status.
    /// @return popped The value removed from the heap during pop or replace operations.
    ///
    /// Steps:
    /// 1. Load the current length of the heap.
    /// 2. Calculate the storage slot offset for the heap array.
    /// 3. Perform operations based on the specified mode:
    ///    - Enqueue: Add value if space is available, otherwise replace the smallest value.
    ///    - Pop: Remove and return the root value.
    ///    - Replace: Replace the root value with the given value.
    ///    - Push: Add value to the heap, ignoring maxLength.
    ///    - PushPop: Add value and immediately pop the smallest value.
    /// 4. Perform sift-up and sift-down operations to maintain heap properties.
    /// 5. Update the heap storage with the new value and return the operation status and popped value.
    function _set(Heap storage heap, uint256 value, uint256 maxLength, uint256 mode)
        private
        returns (uint256 status, uint256 popped)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let n := sload(heap.data.slot)
            mstore(0x00, heap.data.slot)
            let offset := keccak256(0x00, 0x20)

            // Mode 1: Pop
            if eq(mode, 1) {
                if iszero(n) {
                    mstore(0x00, 0xd76f470b) // `HeapIsEmpty()`.
                    revert(0x1c, 0x04)
                }
                popped := sload(offset)
                let last := sload(add(offset, n))
                n := sub(n, 1)
                sstore(heap.data.slot, n)
                if iszero(n) { break }
                sstore(offset, last)
                // Sift down.
                let i := 0
                for {} 1 {} {
                    let c := add(add(i, i), 1)
                    if iszero(lt(c, n)) { break }
                    let cv := sload(add(offset, c))
                    let r := add(c, 1)
                    if lt(r, n) {
                        let rv := sload(add(offset, r))
                        if lt(rv, cv) {
                            c := r
                            cv := rv
                        }
                    }
                    if iszero(lt(cv, last)) { break }
                    sstore(add(offset, i), cv)
                    i := c
                }
                sstore(add(offset, i), last)
                break
            }

            // Mode 2: Replace
            if eq(mode, 2) {
                if iszero(n) {
                    mstore(0x00, 0xd76f470b) // `HeapIsEmpty()`.
                    revert(0x1c, 0x04)
                }
                popped := sload(offset)
                // Sift down.
                let i := 0
                for {} 1 {} {
                    let c := add(add(i, i), 1)
                    if iszero(lt(c, n)) { break }
                    let cv := sload(add(offset, c))
                    let r := add(c, 1)
                    if lt(r, n) {
                        let rv := sload(add(offset, r))
                        if lt(rv, cv) {
                            c := r
                            cv := rv
                        }
                    }
                    if iszero(lt(cv, value)) { break }
                    sstore(add(offset, i), cv)
                    i := c
                }
                sstore(add(offset, i), value)
                status := 3
                break
            }

            // Mode 4: PushPop
            if eq(mode, 4) {
                if iszero(n) {
                    popped := value
                    break
                }
                let root := sload(offset)
                if iszero(lt(value, root)) {
                    popped := root
                    // Sift down with new value.
                    let i := 0
                    for {} 1 {} {
                        let c := add(add(i, i), 1)
                        if iszero(lt(c, n)) { break }
                        let cv := sload(add(offset, c))
                        let r := add(c, 1)
                        if lt(r, n) {
                            let rv := sload(add(offset, r))
                            if lt(rv, cv) {
                                c := r
                                cv := rv
                            }
                        }
                        if iszero(lt(cv, value)) { break }
                        sstore(add(offset, i), cv)
                        i := c
                    }
                    sstore(add(offset, i), value)
                    break
                }
                popped := root
                sstore(offset, value)
                break
            }

            // Mode 0: Enqueue
            if eq(mode, 0) {
                if iszero(lt(n, maxLength)) {
                    let root := sload(offset)
                    if iszero(lt(value, root)) {
                        // Replace root and sift down.
                        let i := 0
                        for {} 1 {} {
                            let c := add(add(i, i), 1)
                            if iszero(lt(c, n)) { break }
                            let cv := sload(add(offset, c))
                            let r := add(c, 1)
                            if lt(r, n) {
                                let rv := sload(add(offset, r))
                                if lt(rv, cv) {
                                    c := r
                                    cv := rv
                                }
                            }
                            if iszero(lt(cv, value)) { break }
                            sstore(add(offset, i), cv)
                            i := c
                        }
                        sstore(add(offset, i), value)
                        popped := root
                        status := 3
                        break
                    }
                    // Value is smaller than root, discard.
                    break
                }
                // Push the value.
                n := add(n, 1)
                sstore(heap.data.slot, n)
                // Sift up.
                let i := sub(n, 1)
                for {} i {} {
                    let p := shr(1, sub(i, 1))
                    let pv := sload(add(offset, p))
                    if iszero(lt(value, pv)) { break }
                    sstore(add(offset, i), pv)
                    i := p
                }
                sstore(add(offset, i), value)
                status := 1
                break
            }

            // Mode 3: Push
            n := add(n, 1)
            sstore(heap.data.slot, n)
            // Sift up.
            let i := sub(n, 1)
            for {} i {} {
                let p := shr(1, sub(i, 1))
                let pv := sload(add(offset, p))
                if iszero(lt(value, pv)) { break }
                sstore(add(offset, i), pv)
                i := p
            }
            sstore(add(offset, i), value)
        }
    }

    /// @notice Internal function to manage heap operations such as enqueue, pop, replace, push, and pushPop.
    ///
    /// @param heap The heap memory reference.
    /// @param value The value to be inserted or compared.
    /// @param maxLength The maximum allowed length of the heap.
    /// @param mode The operation mode:
    ///              - 0: Enqueue (adds value to the heap if space is available).
    ///              - 1: Pop (removes and returns the root value).
    ///              - 2: Replace (replaces the root value with the given value).
    ///              - 3: Push (adds value to the heap, ignoring maxLength).
    ///              - 4: PushPop (adds value and immediately pops the smallest value).
    ///
    /// @return status The status of the operation:
    ///              - 1: Successfully enqueued.
    ///              - 3: Replaced the root value.
    ///              - Other: Operation-specific status.
    /// @return popped The value removed from the heap during pop or replace operations.
    ///
    /// Steps:
    /// 1. Load the current length of the heap.
    /// 2. Get the data pointer from the heap.
    /// 3. Perform operations based on the specified mode:
    ///    - Enqueue: Add value if space is available, otherwise replace the smallest value.
    ///    - Pop: Remove and return the root value.
    ///    - Replace: Replace the root value with the given value.
    ///    - Push: Add value to the heap, ignoring maxLength.
    ///    - PushPop: Add value and immediately pop the smallest value.
    /// 4. Perform sift-up and sift-down operations to maintain heap properties.
    /// 5. Update the heap memory with the new value and return the operation status and popped value.
    function _set(MemHeap memory heap, uint256 value, uint256 maxLength, uint256 mode)
        private
        pure
        returns (uint256 status, uint256 popped)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let d := mload(heap)
            let n := mload(d)

            // Mode 1: Pop
            if eq(mode, 1) {
                if iszero(n) {
                    mstore(0x00, 0xd76f470b) // `HeapIsEmpty()`.
                    revert(0x1c, 0x04)
                }
                popped := mload(add(d, 0x20))
                let last := mload(add(d, add(0x20, shl(5, sub(n, 1)))))
                n := sub(n, 1)
                mstore(d, n)
                if iszero(n) { break }
                mstore(add(d, 0x20), last)
                // Sift down.
                let i := 0
                for {} 1 {} {
                    let c := add(add(i, i), 1)
                    if iszero(lt(c, n)) { break }
                    let cv := mload(add(d, add(0x20, shl(5, c))))
                    let r := add(c, 1)
                    if lt(r, n) {
                        let rv := mload(add(d, add(0x20, shl(5, r))))
                        if lt(rv, cv) {
                            c := r
                            cv := rv
                        }
                    }
                    if iszero(lt(cv, last)) { break }
                    mstore(add(d, add(0x20, shl(5, i))), cv)
                    i := c
                }
                mstore(add(d, add(0x20, shl(5, i))), last)
                break
            }

            // Mode 2: Replace
            if eq(mode, 2) {
                if iszero(n) {
                    mstore(0x00, 0xd76f470b) // `HeapIsEmpty()`.
                    revert(0x1c, 0x04)
                }
                popped := mload(add(d, 0x20))
                // Sift down.
                let i := 0
                for {} 1 {} {
                    let c := add(add(i, i), 1)
                    if iszero(lt(c, n)) { break }
                    let cv := mload(add(d, add(0x20, shl(5, c))))
                    let r := add(c, 1)
                    if lt(r, n) {
                        let rv := mload(add(d, add(0x20, shl(5, r))))
                        if lt(rv, cv) {
                            c := r
                            cv := rv
                        }
                    }
                    if iszero(lt(cv, value)) { break }
                    mstore(add(d, add(0x20, shl(5, i))), cv)
                    i := c
                }
                mstore(add(d, add(0x20, shl(5, i))), value)
                status := 3
                break
            }

            // Mode 4: PushPop
            if eq(mode, 4) {
                if iszero(n) {
                    popped := value
                    break
                }
                let root := mload(add(d, 0x20))
                if iszero(lt(value, root)) {
                    popped := root
                    // Sift down with new value.
                    let i := 0
                    for {} 1 {} {
                        let c := add(add(i, i), 1)
                        if iszero(lt(c, n)) { break }
                        let cv := mload(add(d, add(0x20, shl(5, c))))
                        let r := add(c, 1)
                        if lt(r, n) {
                            let rv := mload(add(d, add(0x20, shl(5, r))))
                            if lt(rv, cv) {
                                c := r
                                cv := rv
                            }
                        }
                        if iszero(lt(cv, value)) { break }
                        mstore(add(d, add(0x20, shl(5, i))), cv)
                        i := c
                    }
                    mstore(add(d, add(0x20, shl(5, i))), value)
                    break
                }
                popped := root
                mstore(add(d, 0x20), value)
                break
            }

            // Mode 0: Enqueue
            if eq(mode, 0) {
                if iszero(lt(n, maxLength)) {
                    let root := mload(add(d, 0x20))
                    if iszero(lt(value, root)) {
                        // Replace root and sift down.
                        let i := 0
                        for {} 1 {} {
                            let c := add(add(i, i), 1)
                            if iszero(lt(c, n)) { break }
                            let cv := mload(add(d, add(0x20, shl(5, c))))
                            let r := add(c, 1)
                            if lt(r, n) {
                                let rv := mload(add(d, add(0x20, shl(5, r))))
                                if lt(rv, cv) {
                                    c := r
                                    cv := rv
                                }
                            }
                            if iszero(lt(cv, value)) { break }
                            mstore(add(d, add(0x20, shl(5, i))), cv)
                            i := c
                        }
                        mstore(add(d, add(0x20, shl(5, i))), value)
                        popped := root
                        status := 3
                        break
                    }
                    // Value is smaller than root, discard.
                    break
                }
                // Push the value.
                n := add(n, 1)
                mstore(d, n)
                // Sift up.
                let i := sub(n, 1)
                for {} i {} {
                    let p := shr(1, sub(i, 1))
                    let pv := mload(add(d, add(0x20, shl(5, p))))
                    if iszero(lt(value, pv)) { break }
                    mstore(add(d, add(0x20, shl(5, i))), pv)
                    i := p
                }
                mstore(add(d, add(0x20, shl(5, i))), value)
                status := 1
                break
            }

            // Mode 3: Push
            n := add(n, 1)
            mstore(d, n)
            // Sift up.
            let i := sub(n, 1)
            for {} i {} {
                let p := shr(1, sub(i, 1))
                let pv := mload(add(d, add(0x20, shl(5, p))))
                if iszero(lt(value, pv)) { break }
                mstore(add(d, add(0x20, shl(5, i))), pv)
                i := p
            }
            mstore(add(d, add(0x20, shl(5, i))), value)
        }
